import {readSaved,removeSaved,clearSaved} from './saved-resources.js';
export function initPage(){
const list=document.querySelector('#saved-list'),status=document.querySelector('#saved-status'),empty=document.querySelector('#saved-empty'),exportButton=document.querySelector('#saved-export'),clearButton=document.querySelector('#saved-clear'),confirm=document.querySelector('#clear-guide');
function draw(){const state=readSaved();list.replaceChildren();status.textContent=state.issue||`${state.items.length} saved ${state.items.length===1?'resource':'resources'}.`;empty.hidden=state.items.length>0;exportButton.disabled=Boolean(state.issue)||!state.items.length;clearButton.disabled=!state.issue&&!state.items.length;
 for(const item of state.items){const li=document.createElement('li');li.className='lesson-detail-card';const title=document.createElement('h2'),a=document.createElement('a');a.href=item.url;a.textContent=item.title;title.append(a);const p=document.createElement('p');p.textContent=item.description;const button=document.createElement('button');button.type='button';button.className='text-link';button.textContent='Remove';button.setAttribute('aria-label',`Remove ${item.title} from field guide`);button.onclick=()=>{const next=li.nextElementSibling?.querySelector('button')||li.previousElementSibling?.querySelector('button');const nextUrl=next?.closest('li').querySelector('a').getAttribute('href');try{removeSaved(item.url);draw();const destination=nextUrl?[...list.querySelectorAll('li')].find(x=>x.querySelector('a').getAttribute('href')===nextUrl)?.querySelector('button'):document.querySelector('#saved-empty a');destination?.focus()}catch(error){status.textContent=error.message}};li.append(title,p,button);list.append(li)}
}
clearButton.onclick=()=>confirm.showModal();document.querySelector('#clear-cancel').onclick=()=>confirm.close();document.querySelector('#clear-confirm').onclick=()=>{try{clearSaved();confirm.close();draw();document.querySelector('#saved-empty a').focus()}catch(error){confirm.close();status.textContent=error.message}};
exportButton.onclick=()=>{const state=readSaved();if(state.issue||!state.items.length){status.textContent=state.issue||'Save a resource before downloading a list.';return}const body='MT E.L.K., INC. — My Field Guide\n\nSaved links only. Videos and documents still require an internet connection and site access.\n\n'+state.items.map(r=>`${r.title}\n${new URL(r.url,location.origin).href}\n${r.description}`).join('\n\n');const url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='MT-ELK-INC-field-guide-links.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
window.addEventListener('field-guide-change',draw);window.addEventListener('storage',draw);draw();

}
if(!window.MTPageRouter?.booting){if(window.MTPageRouter)window.MTPageRouter.run(initPage);else initPage();}
